'use strict';

/* eslint n/no-unsupported-features/es-builtins: ["error", {"version": ">=8.0.0"}] */

/* eslint n/no-unsupported-features/es-syntax: ["error", {"version": ">=8.0.0"}] */


// MODULES //

var DataView = require( '@stdlib/array/dataview' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Int32Array = require( '@stdlib/array/int32' );
var Float64Array = require( '@stdlib/array/float64' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var abs = require( '@stdlib/math/base/special/abs' );
var cases = require( './fixtures/reference.json' ).cases;
var buffer = new ArrayBuffer(8);
var view = new DataView(buffer);


// FUNCTIONS //

/**
* Decodes a reference IEEE binary64 string.
* @private
* @param {string} value - bits
* @returns {number} value
*/
function decode(value) {
	view.setUint32(0, parseInt(value.slice(0, 8), 16));
	view.setUint32(4, parseInt(value.slice(8), 16));
	return view.getFloat64(0);
}
/**
* Encodes a result for exact finite and signed-zero comparison.
* @private
* @param {number} value - value
* @returns {string} bits or NaN class
*/
function bits(value) {
	var hi;
	var lo;
	if ((value !== value)) {
		return 'NaN';
	}
	view.setFloat64(0, value);
	hi = ('00000000' + view.getUint32(0).toString(16)).slice(-8);
	lo = ('00000000' + view.getUint32(4).toString(16)).slice(-8);
	return (hi + lo);
}
/**
* Reconstructs P_A=L_U, swapping previously produced L columns.
* @private
* @param {Object} x - fixture
* @param {Float64Array} ab - factor view
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - offset
* @returns {number} relative maximum residual
*/
function residual(x, ab, r, c, o) {
	var error;
	var scale;
	var value;
	var swap;
	var kv;
	var a;
	var d;
	var i;
	var j;
	var k;
	var l;
	var m;
	var n;
	var p;
	var q;
	var u;
	d = x.dimensions;
	m = d.m;
	n = d.n;
	k = min(m, n);
	kv = (d.kl + d.ku);
	a = x.dense_input_bits.map(decode);
	l = [];
	u = [];
	scale = 0;
	error = 0;
	for (i = 0; (i < m); i += 1) {
		l[i] = [];
		for (j = 0; (j < k); j += 1) {
			l[i][j] = (i === j) ? 1 : 0;
		}
	}
	for (j = 0; (j < k); j += 1) {
		p = (x.pivots_1based[j] - 1);
		for (q = 0; (q < n); q += 1) {
			swap = a[((j * n) + q)];
			a[((j * n) + q)] = a[((p * n) + q)];
			a[((p * n) + q)] = swap;
		}
		for (q = 0; (q < j); q += 1) {
			swap = l[j][q];
			l[j][q] = l[p][q];
			l[p][q] = swap;
		}
		for (i = (j + 1); (i <= min((m - 1), (j + d.kl))); i += 1) {
			l[i][j] = ab[((o + (((kv + i) - j) * r)) + (j * c))];
		}
	}
	for (i = 0; (i < a.length); i += 1) {
		scale = max(scale, abs(a[i]));
	}
	if ((scale === 0)) {
		scale = 1;
	}
	for (i = 0; (i < k); i += 1) {
		u[i] = [];
		for (j = 0; (j < n); j += 1) {
			u[i][j] = ((j >= i) && (j <= (i + kv))) ? (ab[((o + (((kv + i) - j) * r)) + (j * c))] / scale) : 0;
		}
	}
	for (i = 0; (i < m); i += 1) {
		for (j = 0; (j < n); j += 1) {
			value = 0;
			for (q = 0; (q < k); q += 1) {
				value += (l[i][q] * u[q][j]);
			}
			error = max(error, abs((value - (a[((i * n) + j)] / scale))));
		}
	}
	return error;
}
/**
* Runs finite reference, layout, mutation and independent reconstruction tests.
* @private
* @param {Object} t - tape
* @param {Function} f - complete public-signature backend
* @returns {void}
*/
function run(t, f) {
	var expectedPiv;
	var expected;
	var layouts;
	var actual;
	var index;
	var piv;
	var ab;
	var hi;
	var lo;
	var op;
	var sp;
	var c;
	var d;
	var h;
	var i;
	var j;
	var k;
	var o;
	var q;
	var r;
	var x;
	var z;
	layouts = [
		[
			1,
			0,
			1
		],
		[
			2,
			0,
			-2
		],
		[
			-2,
			0,
			2
		],
		[
			1,
			0,
			0
		],
		[
			3,
			0,
			-1
		]
	];
	cases.forEach(function each(item) {
		x = item;
		d = x.dimensions;
		h = (((2 * d.kl) + d.ku) + 1);
		k = min(d.m, d.n);
		if ((k === 0)) {
			t.strictEqual(f('column-major', d.m, d.n, d.kl, d.ku, null, d.ldab, null), 0, (x.case + ' empty'));
			return;
		}
		for (z = 0; (z < layouts.length); z += 1) {
			r = layouts[z][0];
			c = ((h + 3) * abs(r));
			if ((z === 2)) {
				c = -c;
			}
			if ((z === 3)) {
				c = 0;
			}
			if (((d.n > 1) && (c === 0))) {
				c = (h + 3);
			}
			sp = layouts[z][2];
			if (((k > 1) && (sp === 0))) {
				sp = 1;
			}
			lo = (min(((h - 1) * r), 0) + min(((d.n - 1) * c), 0));
			hi = (max(((h - 1) * r), 0) + max(((d.n - 1) * c), 0));
			o = (3 - lo);
			ab = new Float64Array(new ArrayBuffer((((hi - lo) + 10) * 8)), 8, ((hi - lo) + 8));
			ab.fill(91);
			expected = Array.prototype.slice.call(ab);
			for (j = 0; (j < d.n); j += 1) {
				for (i = 0; (i < h); i += 1) {
					index = ((o + (i * r)) + (j * c));
					ab[index] = decode(x.whole_AB_input_bits[((4 + (j * d.ldab)) + i)]);
					expected[index] = decode(x.whole_AB_output_bits[((4 + (j * d.ldab)) + i)]);
				}
			}
			op = (2 - min(((k - 1) * sp), 0));
			piv = new Int32Array(new ArrayBuffer(((abs(((k - 1) * sp)) + 8) * 4)), 4, (abs(((k - 1) * sp)) + 6));
			piv.fill(-777);
			expectedPiv = Array.prototype.slice.call(piv);
			for (q = 0; (q < k); q += 1) {
				expectedPiv[(op + (q * sp))] = x.pivots_1based[q];
			}
			actual = f.ndarray(d.m, d.n, d.kl, d.ku, ab, r, c, o, piv, sp, op);
			t.strictEqual(actual, x.INFO, ((x.case + ' INFO layout') + z));
			t.deepEqual(Array.prototype.slice.call(ab).map(bits), expected.map(bits), ((x.case + ' full AB/guards layout') + z));
			t.deepEqual(Array.prototype.slice.call(piv), expectedPiv, ((x.case + ' full step history/guards layout') + z));
			if ((x.kind === 'finite')) {
				t.ok((residual(x, ab, r, c, o) < 1e-12), ((x.case + ' P*A=L*U layout') + z));
			}
		}
		[
			'column-major',
			'row-major'
		].forEach(function layout(order) {
			r = (order === 'column-major') ? 1 : (d.n + 2);
			c = (order === 'column-major') ? (h + 2) : 1;
			o = 0;
			ab = new Float64Array(((((h - 1) * r) + ((d.n - 1) * c)) + 1));
			ab.fill(91);
			expected = Array.prototype.slice.call(ab);
			for (j = 0; (j < d.n); j += 1) {
				for (i = 0; (i < h); i += 1) {
					index = ((i * r) + (j * c));
					ab[index] = decode(x.whole_AB_input_bits[((4 + (j * d.ldab)) + i)]);
					expected[index] = decode(x.whole_AB_output_bits[((4 + (j * d.ldab)) + i)]);
				}
			}
			piv = new Int32Array(k);
			piv.fill(-999);
			t.strictEqual(f(order, d.m, d.n, d.kl, d.ku, ab, (order === 'column-major') ? c : r, piv), x.INFO, ((x.case + ' main ') + order));
			t.deepEqual(Array.prototype.slice.call(ab).map(bits), expected.map(bits), ((x.case + ' main backing ') + order));
			t.deepEqual(Array.prototype.slice.call(piv), x.pivots_1based, ((x.case + ' main step history ') + order));
		});
	});
}


// EXPORTS //

module.exports = run;
